import com.sun.net.httpserver.HttpServer;
import java.io.*;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.util.regex.*;
public class Main{
 static String numberToWords(String n)throws Exception{String body="<?xml version=\"1.0\" encoding=\"utf-8\"?><soap:Envelope xmlns:soap=\"http://schemas.xmlsoap.org/soap/envelope/\"><soap:Body><NumberToWords xmlns=\"http://www.dataaccess.com/webservicesserver/\"><ubiNum>"+n+"</ubiNum></NumberToWords></soap:Body></soap:Envelope>";HttpRequest req=HttpRequest.newBuilder(URI.create("https://www.dataaccess.com/webservicesserver/NumberConversion.wso")).header("Content-Type","text/xml; charset=utf-8").header("SOAPAction","http://www.dataaccess.com/webservicesserver/NumberToWords").POST(HttpRequest.BodyPublishers.ofString(body)).build();String xml=HttpClient.newHttpClient().send(req,HttpResponse.BodyHandlers.ofString()).body();Matcher m=Pattern.compile("<m:NumberToWordsResult>(.*?)</m:NumberToWordsResult>|<NumberToWordsResult>(.*?)</NumberToWordsResult>").matcher(xml);return m.find()?(m.group(1)!=null?m.group(1):m.group(2)).trim():xml;}
 public static void main(String[]args)throws Exception{HttpServer s=HttpServer.create(new InetSocketAddress(3000),0);s.createContext("/",ex->{String q=ex.getRequestURI().getQuery();String n="10";if(q!=null&&q.startsWith("n="))n=q.substring(2);String r;try{r=numberToWords(n);}catch(Exception e){r="Error SOAP: "+e.getMessage();}byte[]b=r.getBytes(StandardCharsets.UTF_8);ex.sendResponseHeaders(200,b.length);ex.getResponseBody().write(b);ex.close();});s.start();System.out.println("Servidor en http://localhost:3000/?n=10");}}
